from itertools import combinations

def count_monochromatic_triangles(n, R, B):
    """Counts the minimum number of monochromatic triangles for a given partition (R, B) of n."""
    if R < 3:
        count_R = 0
    else:
        # In a complete graph Kr, the number of triangles is C(R, 3)
        import math
        count_R = math.comb(R, 3)

    if B < 3:
        count_B = 0
    else:
        import math
        count_B = math.comb(B, 3)

    return count_R + count_B

def check_smallest_n(target=2):
    print("n | Minimum monochromatic triangles")
    for n in range(1, 8):
        min_triangles = float('inf')

        # Check all partitions R + B = n
        for R in range(n // 2 + 1):
            B = n - R
            if R > B:
                continue

            triangles = count_monochromatic_triangles(n, R, B)
            min_triangles = min(min_triangles, triangles)

        print(f"{n} | {min_triangles}")

    return min_triangles

check_smallest_n()
